                "vault" | "vl" => HELP_VAULT,
                "note" | "nt" => HELP_NOTE,
                "folder" | "fd" => HELP_FOLDER,
                "enter" | "en" => HELP_ENTER,
                "open" | "op" => HELP_OPEN,
                "opdir" | "od" => HELP_OPDIR,
