                "move" | "mv" => HELP_MOVE,
                "vmove" | "vm" => HELP_VMOVE,
                "config" | "cf" => HELP_CONFIG,
                _ => {
                    // unknown help topic? print top?
                    TOP_HELP
                }
            };
            print!("{}", help_content);
            exit(0);
        }
    }
    // Handle subcommands with aliases
