}

fn handle_vault(args: &[String]) {
    // check help
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_VAULT);
        exit(0);
    }
    let mut l_flag = false;
    let mut positional: Vec<String> = Vec::new();
    let mut unknown_flag = None;
    for a in args {
        if a == "-l" {
            l_flag = true;
        } else if a.starts_with('-') {
            unknown_flag = Some(a.clone());
            break;
        } else {
            positional.push(a.clone());
        }
    }
    if let Some(flag) = unknown_flag {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>\n\nFor more information try --help", flag);
        exit(2);
    }
    if l_flag {
        if positional.is_empty() {
            // list with location
            let vaults = load_vaults();
            for (name, loc) in vaults.vaults.iter() {
                println!("   {} \t {}", name, loc);
            }
            exit(0);
        } else if positional.len() == 1 {
            eprintln!("error: The following required arguments were not provided:\n    <vault location>\n\nUSAGE:\n    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>\n\nFor more information try --help");
            exit(2);
        } else if positional.len() == 2 {
            // treat as create?
            let name = positional[0].clone();
            let loc = positional[1].clone();
            do_create_vault(name, loc);
        } else {
            let extra = &positional[2];
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>\n\nFor more information try --help", extra);
            exit(2);
        }
    } else {
        if positional.is_empty() {
            let vaults = load_vaults();
            for (name, _loc) in vaults.vaults.iter() {
                println!("   {}", name);
            }
            exit(0);
        } else if positional.len() == 1 {
            eprintln!("error: The following required arguments were not provided:\n    <vault location>\n\nUSAGE:\n    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>\n\nFor more information try --help");
            exit(2);
        } else if positional.len() == 2 {
            let name = positional[0].clone();
            let loc = positional[1].clone();
            do_create_vault(name, loc);
        } else {
            let extra = &positional[2];
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>\n\nFor more information try --help", extra);
            exit(2);
        }
    }
}

fn do_create_vault(name: String, location_str: String) {
    // validate name invalid
    if is_invalid_name(&name) {
        red_error("invalid name");
        exit(0);
    }
    // check vault already exists
    let mut vaults = load_vaults();
    if vaults.vaults.contains_key(&name) {
        red_error(&format!("vault {} already exists", name));
        exit(0);
    }
    let loc_path = PathBuf::from(&location_str);
    if !loc_path.is_absolute() {
        red_error("specified path isn't absolute");
        exit(0);
    }
    if !loc_path.exists() || !loc_path.is_dir() {
        red_error("couldn't find the path specified");
        exit(0);
    }
    let vault_path = loc_path.join(&name);
    if vault_path.exists() {
        red_error(&format!("a folder named {} already exists in this location", name));
        exit(0);
    }
    // create dir
    if let Err(e) = fs::create_dir_all(&vault_path) {
        // map error to undefined error?
        red_error(&format!("undefined error: {} (os error {})", e.to_string(), e.raw_os_error().unwrap_or(0)));
        exit(0);
    }
    // create .jot dir
    let jot_path = vault_path.join(".jot");
    let _ = fs::create_dir_all(&jot_path);
    let data = VaultData {
        name: name.clone(),
        location: location_str.clone(),
        folder: String::new(),
        history: Vec::new(),
    };
    let data_path = jot_path.join("data");
    save_vault_data(&data_path, &data);
    // update vaults
    vaults.vaults.insert(name.clone(), location_str.clone());
    save_vaults(&vaults);
    println!("vault {} created", blue(&name));
    exit(0);
}

fn handle_note(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_NOTE);
        exit(0);
    }
    // check unknown flag
    for a in args {
        if a.starts_with('-') {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt note\n    jt note [note name]\n\nFor more information try --help", a);
            exit(2);
        }
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <note name>\n\nUSAGE:\n    jt note\n    jt note [note name]\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 1 {
        let extra = &args[1];
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt note\n    jt note [note name]\n\nFor more information try --help", extra);
        exit(2);
    }
    let name = args[0].clone();
    do_create_note(name);
}

fn do_create_note(name: String) {
    // check inside vault
    let vaults = load_vaults();
    let current = match vaults.current {
        Some(ref c) => c.clone(),
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    let loc_str = match vaults.vaults.get(&current) {
        Some(s) => s.clone(),
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    if is_invalid_name(&name) {
        red_error("invalid name");
        exit(0);
    }
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    let current_dir = if vault_data.folder.is_empty() {
        vault_path.clone()
    } else {
        vault_path.join(&vault_data.folder)
    };
    // For note, check folder existence? If current_dir doesn't exist? Should exist.
    let target = current_dir.join(&name).with_extension("md");
    // Check duplicate? Need to check if target exists (file)
    if target.exists() {
        red_error(&format!("a note named {} already exists in this location", name));
        exit(0);
    }
    // Also need to check if target is inside vault? For empty name, target is vault.md sibling outside, but then exists check already? We should still allow creating outside? Original allowed and created file outside. But duplicate check for empty name second time would be true, so error duplicate. For first time, target doesn't exist, so create outside? That seems to be original behavior for empty name: it creates file outside vault, but we should replicate.
    // Also check if parent dir exists? target parent is current_dir, exists.
    // Create file
    match fs::File::create(&target) {
        Ok(_) => {
            println!("note {} created", blue(&name));
            exit(0);
        },
        Err(e) => {
            // map to undefined error? But for invalid like a/b containing slash already caught as invalid name before, so not here.
            // For other errors, we should map.
            // Check if error is due to invalid? Already checked.
            red_error(&format!("undefined error: {} (os error {})", e.to_string(), e.raw_os_error().unwrap_or(0)));
            exit(0);
        }
    }
}

fn handle_folder(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_FOLDER);
        exit(0);
    }
    for a in args {
        if a.starts_with('-') {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt folder\n    jt folder [folder name]\n\nFor more information try --help", a);
            exit(2);
        }
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <folder name>\n\nUSAGE:\n    jt folder\n    jt folder [folder name]\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 1 {
        let extra = &args[1];
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt folder\n    jt folder [folder name]\n\nFor more information try --help", extra);
        exit(2);
    }
    let name = args[0].clone();
    do_create_folder(name);
}

fn do_create_folder(name: String) {
    let vaults = load_vaults();
    let current = match vaults.current {
        Some(ref c) => c.clone(),
        None => { red_error("not inside a vault"); exit(0); }
    };
    let loc_str = match vaults.vaults.get(&current) {
        Some(s) => s.clone(),
        None => { red_error("not inside a vault"); exit(0); }
    };
    if is_invalid_name(&name) {
        red_error("invalid name");
        exit(0);
    }
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => { red_error("not inside a vault"); exit(0); }
    };
    let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
    let target = current_dir.join(&name);
    if target.exists() {
        red_error(&format!("a folder named {} already exists in this location", name));
        exit(0);
    }
    match fs::create_dir(&target) {
        Ok(_) => { println!("folder {} created", blue(&name)); exit(0); },
        Err(e) => {
            red_error(&format!("undefined error: {} (os error {})", e.to_string(), e.raw_os_error().unwrap_or(0)));
            exit(0);
        }
    }
}

fn handle_enter(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_ENTER);
        exit(0);
    }
    for a in args {
        if a.starts_with('-') {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable enter <vault name>\n\nFor more information try --help", a);
            exit(2);
        }
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <vault name>\n\nUSAGE:\n    executable enter <vault name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 1 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable enter <vault name>\n\nFor more information try --help", args[1]);
        exit(2);
    }
    let name = args[0].clone();
    let mut vaults = load_vaults();
    if !vaults.vaults.contains_key(&name) {
        red_error(&format!("vault {} doesn't exist", name));
        exit(0);
    }
    if let Some(ref cur) = vaults.current {
        if cur == &name {
            red_error(&format!("already in vault {}", name));
            exit(0);
        }
    }
    vaults.current = Some(name.clone());
    save_vaults(&vaults);
    println!("entered {}", blue(&name));
    exit(0);
}

fn handle_open(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_OPEN);
        exit(0);
    }
    for a in args {
        if a.starts_with('-') {
