    };
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => { red_error("not inside a vault"); exit(0); }
    };
    let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
    let target = current_dir.join(&name).with_extension("md");
    // Also try handling name already contains .md? with_extension will handle, but we also need to handle name like "test.md" where target is test.md, same.
    // Check if target exists as file
    if !target.exists() || !target.is_file() {
        // Also try alternative? But with_extension already handles. If not found, try exact name without extension?
        // For note, target with .md may not be found, but note could be stored as something else? No.
        red_error(&format!("note {} not found", name));
        exit(0);
    }
    // load editor
    let config = load_config();
    let editor = config.editor.clone();
    // split editor into command and args
    let parts: Vec<String> = editor.split_whitespace().map(|s| s.to_string()).collect();
    if parts.is_empty() {
        red_error("editor not found");
        exit(0);
    }
    let cmd = &parts[0];
    let cmd_args = &parts[1..];
    let mut command = Command::new(cmd);
    for a in cmd_args {
        command.arg(a);
    }
    command.arg(&target);
    match command.status() {
        Ok(status) => {
            // if cat, it will have printed; we just exit
            exit(status.code().unwrap_or(0));
        },
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                red_error("editor not found");
                exit(0);
            } else {
                red_error(&format!("undefined error: {} (os error {})", e.to_string(), e.raw_os_error().unwrap_or(0)));
                exit(0);
            }
        }
    }
