            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let old_path = current_dir.join(&old);
            if !old_path.exists() || !old_path.is_dir() {
                red_error(&format!("folder {} not found", old));
                exit(0);
            }
            let new_path = current_dir.join(&new);
            match fs::rename(&old_path, &new_path) {
                Ok(_) => {
                    println!("folder {} renamed to {}", blue(&old), blue(&new));
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'\n\t[possible values: vault, vl, note, nt, folder, fd]\n\nFor more information try --help", item_type);
            exit(2);
        }
    }
