fn do_create_note(name: String) {
    // check inside vault
    let vaults = load_vaults();
    let current = match vaults.current {
        Some(ref c) => c.clone(),
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    let loc_str = match vaults.vaults.get(&current) {
        Some(s) => s.clone(),
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    if is_invalid_name(&name) {
        red_error("invalid name");
        exit(0);
    }
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => {
            red_error("not inside a vault");
            exit(0);
        }
    };
    let current_dir = if vault_data.folder.is_empty() {
        vault_path.clone()
    } else {
        vault_path.join(&vault_data.folder)
    };
    // For note, check folder existence? If current_dir doesn't exist? Should exist.
    let target = current_dir.join(&name).with_extension("md");
    // Check duplicate? Need to check if target exists (file)
    if target.exists() {
        red_error(&format!("a note named {} already exists in this location", name));
        exit(0);
    }
    // Also need to check if target is inside vault? For empty name, target is vault.md sibling outside, but then exists check already? We should still allow creating outside? Original allowed and created file outside. But duplicate check for empty name second time would be true, so error duplicate. For first time, target doesn't exist, so create outside? That seems to be original behavior for empty name: it creates file outside vault, but we should replicate.
    // Also check if parent dir exists? target parent is current_dir, exists.
    // Create file
    match fs::File::create(&target) {
        Ok(_) => {
            println!("note {} created", blue(&name));
            exit(0);
        },
        Err(e) => {
            // map to undefined error? But for invalid like a/b containing slash already caught as invalid name before, so not here.
            // For other errors, we should map.
            // Check if error is due to invalid? Already checked.
            red_error(&format!("undefined error: {} (os error {})", e.to_string(), e.raw_os_error().unwrap_or(0)));
            exit(0);
        }
    }
}

