fn handle_chdir(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_CHDIR);
        exit(0);
    }
    for a in args {
        if a.starts_with('-') && a != "-" && a != "--" {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable chdir <folder path>\n\nFor more information try --help", a);
            exit(2);
        }
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <folder path>\n\nUSAGE:\n    executable chdir <folder path>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 1 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable chdir <folder path>\n\nFor more information try --help", args[1]);
        exit(2);
    }
    let target_str = args[0].clone();
    let vaults = load_vaults();
    let current = match vaults.current.clone() {
        Some(c) => c,
        None => { red_error("not inside a vault"); exit(0); }
    };
    let loc_str = match vaults.vaults.get(&current) {
        Some(s) => s.clone(),
        None => { red_error("not inside a vault"); exit(0); }
    };
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let mut vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => { red_error("not inside a vault"); exit(0); }
    };
    let current_dir = if vault_data.folder.is_empty() {
        vault_path.clone()
    } else {
        vault_path.join(&vault_data.folder)
    };
    // Determine new path
    let new_path_raw: PathBuf = if Path::new(&target_str).is_absolute() {
        PathBuf::from(&target_str)
    } else {
        current_dir.join(&target_str)
    };
    // Check same location? Compare canonical or raw?
    // Use canonical where possible
    let vault_canonical = vault_path.canonicalize().unwrap_or(vault_path.clone());
    let current_canonical = current_dir.canonicalize().unwrap_or(current_dir.clone());
    let new_canonical = new_path_raw.canonicalize().unwrap_or(new_path_raw.clone());
    if new_canonical == current_canonical {
        red_error("new location is same as old location");
        exit(0);
    }
    // Check crosses the bounds: if new_path doesn't start with vault_path after canonicalization
    // For paths that don't exist, canonicalize fails, so we need to check by normalizing components without filesystem?
    // Approach: if new_path_raw exists, check canonical starts_with vault_canonical
    // If not exists, we can't canonicalize, but we can check if normalized path (with .. resolved) would be outside.
    // Simplest: if new_path_raw exists, check canonical; else check if normalized string would be outside?
    // For our purposes, handle crossing for .. from root and absolute /
    // We'll try to detect crossing by checking if new_path_raw canonical not inside, or if new_path_raw contains `..` that goes beyond vault.

    // First, if new_path_raw exists, check canonical
    if new_path_raw.exists() {
        if let Ok(canonical) = new_path_raw.canonicalize() {
            if !canonical.starts_with(&vault_canonical) {
                red_error("path crosses the bounds of vault");
                exit(0);
            }
        } else {
            // fallback
            if !new_path_raw.starts_with(&vault_path) {
                // This may catch absolute paths like /a which not start with vault
                // But for vault/.. case, new_path_raw = vault/.. which does start_with vault (as Path), so not catching
                // Need better handling: for vault/.. that exists, canonical is parent, so we already handled.
                // For non-existing absolute /a, new_path_raw = /a, not start_with vault, so we can treat as couldn't find? But original gave couldn't find for /a, not crosses.
                // So for not exists case, we should not give crosses, just couldn't find. So only crosses when exists and canonical outside.
            }
        }
    } else {
        // not exists => check if path would cross if it existed? For .. from root, new_path_raw = vault/.. which exists, so handled above.
        // For a/../b where b not exists, new_path_raw = vault/a/../b not exists, but its parent vault/a exists, and canonical of parent? Could be inside vault? For our tests, a/../b from a where b not exists at parent? Actually a/../b is vault/b, which exists as sibling? But if b not exists, then new_path_raw not exists => should give couldn't find.
        // So for not exists, we don't check crossing, just give couldn't find.
        // However for absolute / which exists and outside, we already handled.
        // For relative .. that doesn't exist? .. always exists if parent exists, so handled.
        // So for not exists, we can skip crossing check and go to not found.
    }

    if !new_path_raw.exists() || !new_path_raw.is_dir() {
        red_error("couldn't find the path specified");
        exit(0);
    }
    // At this point, new_path exists and is inside vault (if it was outside we already errored crossing)
    // Also need to check crossing for existing path that is inside vault but canonical outside? Already handled.

    // Success: compute new folder relative to vault_path
    let new_folder = match new_path_raw.canonicalize() {
        Ok(canon) => {
            match canon.strip_prefix(&vault_canonical) {
                Ok(rel) => rel.to_string_lossy().to_string(),
                Err(_) => {
                    // shouldn't happen as we checked starts_with
                    red_error("path crosses the bounds of vault");
                    exit(0);
                }
            }
        },
        Err(_) => {
            // fallback: strip prefix without canonical
            match new_path_raw.strip_prefix(&vault_path) {
                Ok(rel) => rel.to_string_lossy().to_string(),
                Err(_) => {
                    red_error("path crosses the bounds of vault");
                    exit(0);
                }
            }
        }
    };
    vault_data.folder = new_folder;
    save_vault_data(&data_path, &vault_data);
    println!("folder changed");
    exit(0);
}

fn handle_list(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_LIST);
        exit(0);
    }
    let filter = if args.is_empty() {
        None
    } else if args.len() == 1 {
        let f = args[0].as_str();
        match f {
            "note" | "nt" | "folder" | "fd" => Some(f.to_string()),
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<item type>'\n\t[possible values: note, nt, folder, fd]\n\nFor more information try --help", f);
                exit(2);
            }
        }
    } else {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable list [item type]\n\nFor more information try --help", args[1]);
        exit(2);
    };
    let vaults = load_vaults();
    let current = match vaults.current {
        Some(ref c) => c.clone(),
        None => { red_error("not inside a vault"); exit(0); }
    };
    let loc_str = match vaults.vaults.get(&current) {
        Some(s) => s.clone(),
        None => { red_error("not inside a vault"); exit(0); }
    };
    let vault_path = PathBuf::from(&loc_str).join(&current);
    let data_path = vault_path.join(".jot").join("data");
    let vault_data = match load_vault_data(&data_path) {
        Some(d) => d,
        None => { red_error("not inside a vault"); exit(0); }
    };
    let current_dir = if vault_data.folder.is_empty() {
        vault_path.clone()
    } else {
        vault_path.join(&vault_data.folder)
    };
    // header
    let header = if vault_data.folder.is_empty() {
        current.clone()
    } else {
        format!("{} > {}", current, vault_data.folder)
    };
    println!("{}", header);
    match filter {
        None => {
            // recursive
            print_tree_recursive(&current_dir, "", true, &mut Vec::new());
        },
        Some(ref f) if f=="note" || f=="nt" => {
            // only immediate notes
            let entries = fs::read_dir(&current_dir).unwrap_or_else(|_| { red_error("not inside a vault"); exit(0); });
            let mut notes: Vec<String> = Vec::new();
            for e in entries {
                if let Ok(entry) = e {
                    let p = entry.path();
                    if p.is_file() {
                        if let Some(ext) = p.extension() {
                            if ext == "md" {
                                let name = p.file_stem().unwrap().to_string_lossy().to_string();
                                notes.push(name);
                            }
                        }
                    }
                }
            }
            // Note: order is filesystem order (read_dir order). We keep as collected (no sort)
            for (i, name) in notes.iter().enumerate() {
                let is_last = i == notes.len() - 1;
                let prefix = if is_last { "└── " } else { "├── " };
                println!("{}{}", prefix, blue(name));
            }
        },
        Some(ref f) if f=="folder" || f=="fd" => {
            let entries = fs::read_dir(&current_dir).unwrap_or_else(|_| { red_error("not inside a vault"); exit(0); });
            let mut folders: Vec<String> = Vec::new();
            for e in entries {
                if let Ok(entry) = e {
                    let p = entry.path();
                    if p.is_dir() {
                        let name = p.file_name().unwrap().to_string_lossy().to_string();
                        // For folder filter, include .jot as well (as observed)
                        folders.push(name);
                    }
                }
            }
            for (i, name) in folders.iter().enumerate() {
                let is_last = i == folders.len() - 1;
                let prefix = if is_last { "└── " } else { "├── " };
                println!("{}{}", prefix, name);
            }
        },
        _ => {}
    }
    exit(0);
}

fn print_tree_recursive(dir: &Path, prefix: &str, is_root: bool, _stack: &mut Vec<bool>) {
    // This function prints tree for plain list (recursive)
    // We'll collect entries, filter out .jot, separate files and dirs, but need to maintain filesystem order? Original shows dirs first then notes? Actually earlier mixed example: at root with n1 (note) and f1 (folder) and f2 etc, plain output showed n1, f1, n2 etc but order was as filesystem? In mixed test, creation order was n1, f1, n2, f2, but plain output for root with n1, f1, n2, f2? Let's see earlier: we created n1, f1, n2, f2 in that order, and plain output at root showed:
    // v1
    // ├── n1
    // ├── f1
    // ├── n2
    // └── f2
    // That's creation order (n1, f1, n2, f2). So order is read_dir order (creation)
    // For nested, they interleave dirs and notes? The tree building recurses into dirs before printing next sibling? In example with a containing c, d, n1 and b at root, output was:
    // v1
    // ├── a
    // │   ├── c
    // │   │   └── n2
    // │   ├── d
    // │   └── n1
    // └── b
    // That's recursive depth-first.

    // Collect entries in read_dir order
    let entries: Vec<_> = match fs::read_dir(dir) {
        Ok(r) => r.filter_map(|e| e.ok()).collect(),
        Err(_) => return,
    };
    // Filter and sort? Keep order as read_dir (which is filesystem order). For plain, we should exclude .jot and list notes and folders.
    // But need to decide order: original read_dir order is filesystem hash order, not sorted, but for our small test it matched creation order.
    // We'll keep order as collected, but need to separate? Actually read_dir order already interleaves files and dirs in creation order, so we can just iterate in that order.

    // Build list of (path, is_dir, display_name, is_note)
    let mut items: Vec<(PathBuf, bool, String, bool)> = Vec::new();
    for entry in entries {
        let p = entry.path();
        let name_os = p.file_name().unwrap().to_string_lossy().to_string();
        if name_os == ".jot" {
            continue;
        }
        if p.is_dir() {
            let display = if name_os.ends_with(".md") {
                name_os[..name_os.len()-3].to_string()
            } else {
                name_os.clone()
            };
            items.push((p, true, display, false));
        } else if p.is_file() {
            if let Some(ext) = p.extension() {
                if ext == "md" {
                    let stem = p.file_stem().unwrap().to_string_lossy().to_string();
                    items.push((p, false, stem, true));
                }
            }
        }
    }
    // For plain, we need to print items with tree prefixes. But we need to handle recursive for dirs.
    // We'll use iterative with stack of prefixes.

    for (idx, (path, is_dir, display, is_note)) in items.iter().enumerate() {
        let is_last = idx == items.len() - 1;
        let branch = if is_last { "└── " } else { "├── " };
        let colored_display = if *is_note { blue(display) } else { display.clone() };
        println!("{}{}{}", prefix, branch, colored_display);
        if *is_dir {
            let new_prefix = if is_last {
                format!("{}    ", prefix)
            } else {
                format!("{}│   ", prefix)
            };
            // recurse
            print_tree_recursive_inner(path, &new_prefix);
        }
    }
}

fn print_tree_recursive_inner(dir: &Path, prefix: &str) {
    let entries: Vec<_> = match fs::read_dir(dir) {
        Ok(r) => r.filter_map(|e| e.ok()).collect(),
        Err(_) => return,
    };
    let mut items: Vec<(PathBuf, bool, String, bool)> = Vec::new();
    for entry in entries {
        let p = entry.path();
        let name_os = p.file_name().unwrap().to_string_lossy().to_string();
        if name_os == ".jot" { continue; }
        if p.is_dir() {
            let display = if name_os.ends_with(".md") { name_os[..name_os.len()-3].to_string() } else { name_os.clone() };
            items.push((p, true, display, false));
        } else if p.is_file() {
            if let Some(ext) = p.extension() {
                if ext == "md" {
                    let stem = p.file_stem().unwrap().to_string_lossy().to_string();
                    items.push((p, false, stem, true));
                }
            }
        }
    }
    for (idx, (path, is_dir, display, is_note)) in items.iter().enumerate() {
        let is_last = idx == items.len() - 1;
        let branch = if is_last { "└── " } else { "├── " };
        let colored_display = if *is_note { blue(display) } else { display.clone() };
        println!("{}{}{}", prefix, branch, colored_display);
        if *is_dir {
            let new_prefix = if is_last { format!("{}    ", prefix) } else { format!("{}│   ", prefix) };
            print_tree_recursive_inner(path, &new_prefix);
        }
    }
}

fn handle_remove(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_REMOVE);
        exit(0);
    }
    // validate item type and name required
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <item type>\n    <name>\n\nUSAGE:\n    executable remove <item type> <name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <name>\n\nUSAGE:\n    executable remove <item type> <name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 2 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable remove <item type> <name>\n\nFor more information try --help", args[2]);
        exit(2);
    }
    let item_type = args[0].as_str();
    let name = args[1].clone();
    match item_type {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                red_error(&format!("vault {} doesn't exist", name));
                exit(0);
            }
            let loc = vaults.vaults[&name].clone();
            let vault_path = PathBuf::from(&loc).join(&name);
            let _ = fs::remove_dir_all(&vault_path);
            vaults.vaults.remove(&name);
            if let Some(cur) = vaults.current.clone() {
                if cur == name {
                    vaults.current = None;
                }
            }
            save_vaults(&vaults);
            println!("vault {} removed", blue(&name));
            exit(0);
        },
        "note" | "nt" => {
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let target = current_dir.join(&name).with_extension("md");
            if !target.exists() || !target.is_file() {
                red_error(&format!("note {} not found", name));
                exit(0);
            }
            match fs::remove_file(&target) {
                Ok(_) => { println!("note {} removed", blue(&name)); exit(0); },
                Err(e) => { red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0))); exit(0); }
            }
        },
        "folder" | "fd" => {
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let target = current_dir.join(&name);
            if !target.exists() || !target.is_dir() {
                red_error(&format!("folder {} not found", name));
                exit(0);
            }
            match fs::remove_dir_all(&target) {
                Ok(_) => { println!("folder {} removed", blue(&name)); exit(0); },
                Err(e) => { red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0))); exit(0); }
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'\n\t[possible values: vault, vl, note, nt, folder, fd]\n\nFor more information try --help", item_type);
            exit(2);
        }
    }
}

fn handle_rename(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_RENAME);
        exit(0);
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <item type>\n    <name>\n    <new name>\n\nUSAGE:\n    executable rename <item type> <name> <new name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <name>\n    <new name>\n\nUSAGE:\n    executable rename <item type> <name> <new name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:\n    <new name>\n\nUSAGE:\n    executable rename <item type> <name> <new name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable rename <item type> <name> <new name>\n\nFor more information try --help", args[3]);
        exit(2);
    }
    let item_type = args[0].as_str();
    let old = args[1].clone();
    let new = args[2].clone();
    match item_type {
        "vault" | "vl" => {
            if is_invalid_name(&new) {
                red_error("invalid name");
                exit(0);
            }
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&old) {
                red_error(&format!("vault {} doesn't exist", old));
                exit(0);
            }
            if vaults.vaults.contains_key(&new) {
                red_error(&format!("vault {} already exists", new));
                exit(0);
            }
            // Also check filesystem exists? For vault rename same as create, if new name folder already exists in location?
            let loc_str = vaults.vaults[&old].clone();
            let old_path = PathBuf::from(&loc_str).join(&old);
            let new_path = PathBuf::from(&loc_str).join(&new);
            if new_path.exists() {
                // This would be `a folder named X already exists`? But for vault rename duplicate, they already checked vaults map, so this case maybe not needed.
                // For vault rename where folder exists but vault not in map? Not.
            }
            match fs::rename(&old_path, &new_path) {
                Ok(_) => {
                    // update vaults map
                    let loc = vaults.vaults.remove(&old).unwrap();
                    vaults.vaults.insert(new.clone(), loc.clone());
                    // update current if needed
                    if let Some(cur) = vaults.current.clone() {
                        if cur == old {
                            vaults.current = Some(new.clone());
                        }
                    }
                    save_vaults(&vaults);
                    // update vault data's name
                    let new_data_path = new_path.join(".jot").join("data");
                    if let Some(mut data) = load_vault_data(&new_data_path) {
                        data.name = new.clone();
                        save_vault_data(&new_data_path, &data);
                    } else {
                        // data was moved, path already new_path, so load from new path
                        let old_data_path = old_path.join(".jot").join("data");
                        // old_data already moved, so new_data_path is correct
                    }
                    println!("vault {} renamed to {}", blue(&old), blue(&new));
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        },
        "note" | "nt" => {
            if old == new {
                red_error("new name is same as old name");
                exit(0);
            }
            if is_invalid_name(&new) {
                red_error("invalid name");
                exit(0);
            }
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let old_path = current_dir.join(&old).with_extension("md");
            // Also handle case where old is like "test.md" already with extension? with_extension will normalize, but old_path as constructed with .md will correctly point to test.md for both old="test" and old="test.md". However if old="test.md" we constructed join("test.md").with_extension("md") = test.md, same as old="test". So both work.
            if !old_path.exists() || !old_path.is_file() {
                red_error(&format!("note {} not found", old));
                exit(0);
            }
            let new_path = current_dir.join(&new).with_extension("md");
            // Check new name invalid already done
            match fs::rename(&old_path, &new_path) {
                Ok(_) => {
                    println!("note {} renamed to {}", blue(&old), blue(&new));
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        },
        "folder" | "fd" => {
            if old == new {
                red_error("new name is same as old name");
                exit(0);
            }
            if is_invalid_name(&new) {
                red_error("invalid name");
                exit(0);
            }
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let old_path = current_dir.join(&old);
            if !old_path.exists() || !old_path.is_dir() {
                red_error(&format!("folder {} not found", old));
                exit(0);
            }
            let new_path = current_dir.join(&new);
            match fs::rename(&old_path, &new_path) {
                Ok(_) => {
                    println!("folder {} renamed to {}", blue(&old), blue(&new));
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'\n\t[possible values: vault, vl, note, nt, folder, fd]\n\nFor more information try --help", item_type);
            exit(2);
        }
    }
}

fn handle_move(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_MOVE);
        exit(0);
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <item type>\n    <name>\n    <new location>\n\nUSAGE:\n    executable move <item type> <name> <new location>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <name>\n    <new location>\n\nUSAGE:\n    executable move <item type> <name> <new location>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:\n    <new location>\n\nUSAGE:\n    executable move <item type> <name> <new location>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable move <item type> <name> <new location>\n\nFor more information try --help", args[3]);
        exit(2);
    }
    let item_type = args[0].as_str();
    let name = args[1].clone();
    let new_loc_str = args[2].clone();
    match item_type {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                red_error(&format!("vault {} doesn't exist", name));
                exit(0);
            }
            let new_loc_path = PathBuf::from(&new_loc_str);
            if !new_loc_path.is_absolute() {
                red_error("specified path isn't absolute");
                exit(0);
            }
            if !new_loc_path.exists() || !new_loc_path.is_dir() {
                red_error("no such file or directory (os error 2)");
                exit(0);
            }
            let old_loc_str = vaults.vaults[&name].clone();
            let old_path = PathBuf::from(&old_loc_str).join(&name);
            let new_path = new_loc_path.join(&name);
            if new_path.exists() {
                red_error(&format!("a folder named {} already exists in this location", name));
                exit(0);
            }
            match fs::rename(&old_path, &new_path) {
                Ok(_) => {
                    vaults.vaults.insert(name.clone(), new_loc_str.clone());
                    save_vaults(&vaults);
                    // update data location
                    let new_data_path = new_path.join(".jot").join("data");
                    if let Some(mut data) = load_vault_data(&new_data_path) {
                        data.location = new_loc_str.clone();
                        save_vault_data(&new_data_path, &data);
                    }
                    println!("vault {} moved", blue(&name));
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("no such file or directory (os error {})", e.raw_os_error().unwrap_or(2)));
                    exit(0);
                }
            }
        },
        "note" | "nt" | "folder" | "fd" => {
            let is_note = item_type == "note" || item_type == "nt";
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let old_path = if is_note {
                current_dir.join(&name).with_extension("md")
            } else {
                current_dir.join(&name)
            };
            // Check old exists
            if !old_path.exists() {
                // For move, original gave "couldn't find the path specified" for note not found? But we saw earlier move note nonexist gave something else.
