            // Check new location
            let new_loc_path = if Path::new(&new_loc_str).is_absolute() {
                PathBuf::from(&new_loc_str)
            } else {
                current_dir.join(&new_loc_str)
            };
            // Check same location?
            // For note, old_path parent is current_dir, new_loc_path is dest dir.
            // If new_loc_path == current_dir (e.g., new_loc_str == "."), then new_target would be same as old_path? Then same location error.
            // Determine dest dir canonical?
            // First, check if new_loc_path == current_dir (same location)
            // We'll compare canonical where possible.
            let dest_dir = new_loc_path.clone();
            // Same location check: if dest_dir == current_dir (for note/folder at same level) then new_target == old_path => same location.
            // But we need to handle dest_dir with trailing slash etc. Compare canonical.
            let current_canonical = current_dir.canonicalize().unwrap_or(current_dir.clone());
            let dest_canonical = dest_dir.canonicalize().unwrap_or(dest_dir.clone());
            if dest_canonical == current_canonical {
                // This corresponds to new_loc "." or "" etc where dest is same as current
                red_error("new location is same as old location");
                exit(0);
            }
            // Check dest_dir exists and is_dir
            if !dest_dir.exists() || !dest_dir.is_dir() {
                red_error("couldn't find the path specified");
                exit(0);
            }
            // Check crosses the bounds: if dest_dir canonical not inside vault
            let vault_canonical = vault_path.canonicalize().unwrap_or(vault_path.clone());
            if let Ok(canon) = dest_dir.canonicalize() {
                if !canon.starts_with(&vault_canonical) {
                    red_error("path crosses the bounds of vault");
                    exit(0);
                }
            } else {
