fn handle_vmove(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_VMOVE);
        exit(0);
    }
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <item type>\n    <name>\n    <vault name>\n\nUSAGE:\n    executable vmove <item type> <name> <vault name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <name>\n    <vault name>\n\nUSAGE:\n    executable vmove <item type> <name> <vault name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:\n    <vault name>\n\nUSAGE:\n    executable vmove <item type> <name> <vault name>\n\nFor more information try --help");
        exit(2);
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable vmove <item type> <name> <vault name>\n\nFor more information try --help", args[3]);
        exit(2);
    }
    let item_type = args[0].as_str();
    let name = args[1].clone();
    let dest_vault = args[2].clone();
    match item_type {
        "note" | "nt" | "folder" | "fd" => {
            let is_note = item_type == "note" || item_type == "nt";
            let vaults = load_vaults();
            let current = match vaults.current { Some(ref c)=>c.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            let loc_str = match vaults.vaults.get(&current) { Some(s)=>s.clone(), None=>{ red_error("not inside a vault"); exit(0); } };
            if !vaults.vaults.contains_key(&dest_vault) {
                red_error(&format!("vault {} doesn't exist", dest_vault));
                exit(0);
            }
            let dest_loc = vaults.vaults[&dest_vault].clone();
            let vault_path = PathBuf::from(&loc_str).join(&current);
            let dest_vault_path = PathBuf::from(&dest_loc).join(&dest_vault);
            let data_path = vault_path.join(".jot").join("data");
            let vault_data = match load_vault_data(&data_path) { Some(d)=>d, None=>{ red_error("not inside a vault"); exit(0); } };
            let current_dir = if vault_data.folder.is_empty() { vault_path.clone() } else { vault_path.join(&vault_data.folder) };
            let old_path = if is_note {
                current_dir.join(&name).with_extension("md")
            } else {
                current_dir.join(&name)
            };
            if !old_path.exists() {
                // Original gave "no such file or directory (os error 2)" for vmove when note not in current folder?
                // Let's check: earlier vmove note nonexist gave that.
                red_error("no such file or directory (os error 2)");
                exit(0);
            }
            let new_target = if is_note {
                dest_vault_path.join(&name).with_extension("md")
            } else {
                dest_vault_path.join(&name)
            };
            if new_target.exists() {
                if is_note {
                    red_error(&format!("a note named {} already exists in this location", name));
                } else {
                    red_error(&format!("a folder named {} already exists in this location", name));
                }
                exit(0);
            }
            // also check if dest vault is same as current vault? Then maybe error? But not needed.
            match fs::rename(&old_path, &new_target) {
                Ok(_) => {
                    if is_note {
                        println!("note {} moved to vault {}", blue(&name), blue(&dest_vault));
                    } else {
                        println!("folder {} moved to vault {}", blue(&name), blue(&dest_vault));
                    }
                    exit(0);
                },
                Err(e) => {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'\n\t[possible values: note, nt, folder, fd]\n\nFor more information try --help", item_type);
            exit(2);
        }
    }
}

fn handle_config(args: &[String]) {
    if args.iter().any(|a| a=="-h" || a=="--help") {
        print!("{}", HELP_CONFIG);
        exit(0);
    }
    if args.is_empty() {
        // open config
        let config_path = get_config_path();
        let cfg = load_config();
        let editor = cfg.editor.clone();
        if editor.is_empty() {
            red_error("editor not found");
            exit(0);
        }
        let parts: Vec<String> = editor.split_whitespace().map(|s| s.to_string()).collect();
        if parts.is_empty() {
            red_error("editor not found");
            exit(0);
        }
        let mut cmd = Command::new(&parts[0]);
        for a in &parts[1..] {
            cmd.arg(a);
        }
        cmd.arg(&config_path);
        match cmd.status() {
            Ok(st) => exit(st.code().unwrap_or(0)),
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    red_error("editor not found");
                    exit(0);
                } else {
                    red_error(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    exit(0);
                }
            }
        }
    }
    if args.len() == 1 {
        let typ = args[0].as_str();
        match typ {
            "editor" => {
                let cfg = load_config();
                println!("editor: {}", blue(&cfg.editor));
                exit(0);
            },
            "conflict" => {
                let cfg = load_config();
                println!("conflict: {}", blue(&cfg.conflict.to_string()));
                exit(0);
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'\n\t[possible values: editor, conflict]\n\nFor more information try --help", typ);
                exit(2);
            }
        }
    }
    if args.len() == 2 {
        let typ = args[0].as_str();
        let val = args[1].clone();
        match typ {
            "editor" => {
                let mut cfg = load_config();
                cfg.editor = val.clone();
                save_config(&cfg);
                println!("set {} to {}", blue("editor"), blue(&val));
                exit(0);
            },
            "conflict" => {
                // This should panic on invalid bool like original
                // Original panics at src/state/config.rs:74:42
                // We replicate panic message manually
                match val.parse::<bool>() {
                    Ok(b) => {
                        let mut cfg = load_config();
                        cfg.conflict = b;
                        save_config(&cfg);
                        println!("set {} to {}", blue("conflict"), blue(&val));
                        exit(0);
                    },
                    Err(_) => {
                        eprintln!("thread 'main' panicked at src/state/config.rs:74:42:\ncalled `Result::unwrap()` on an `Err` value: ParseBoolError\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                        exit(101);
                    }
                }
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'\n\t[possible values: editor, conflict]\n\nFor more information try --help", typ);
                exit(2);
            }
        }
    }
    // args len >2
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    jt config <config type>\n    jt config <config type> [config value]\n\nFor more information try --help", args[2]);
    exit(2);
}
